import org.junit.Test;
import static org.junit.Assert.*;
import java.io.File;
import java.io.IOException;
import java.util.HashMap;

public class EpubCheckerTest {

    @Test
    public void getLocale_emptyLocaleReturnsDefault() {
        Locale locale = new EpubChecker().getLocale();
        assertEquals(Locale.getDefault(), locale);
    }

    @Test
    public void run_validEpubFile_runsSuccessfully() throws Exception {
        EpubChecker epubChecker = new EpubChecker();
        String[] args = { "test.epub", "--verbose" };
        int result = epubChecker.run(args);
        assertTrue(result == 0);
    }

    @Test
    public void run_invalidEpubFile_returnsError() throws Exception {
        EpubChecker epubChecker = new EpubChecker();
        String[] args = { "test.epub", "--invalid" };
        int result = epubChecker.run(args);
        assertTrue(result != 0);
    }

    @Test
    public void getLocale_nullReturnsDefault() {
        Locale locale = new EpubChecker().getLocale(null);
        assertEquals(Locale.getDefault(), locale);
    }

    @Test
    public void validateFile_validEpubFile_returnsZero() throws Exception {
        EpubChecker epubChecker = new EpubChecker();
        String path = "test.epub";
        EPUBVersion version = EPUBVersion.v3;
        int result = epubChecker.validateFile(path, version, null, null);
        assertTrue(result == 0);
    }

    @Test
    public void validateFile_invalidEpubFile_returnsNonZero() throws Exception {
        EpubChecker epubChecker = new EpubChecker();
        String path = "test.epub";
        EPUBVersion version = EPUBVersion.v3;
        int result = epubChecker.validateFile(path, version, null, null);
        assertTrue(result != 0);
    }
}
